CAT = "ngarmyGrammar"; SEG = "GRM"
Q = [
("Which sentence uses \"cannot help\" correctly?",
 "The recruits could not help laughing at the joke.", ["The recruits could not help to laugh at the joke.", "The recruits could not help laughed at the joke.", "The recruits could not help but laughing at the joke."],
 "\"Cannot help\", meaning cannot stop oneself, is followed by the -ing form: \"could not help laughing\"."),
("Which sentence uses \"raise\" or \"rise\" correctly?",
 "The guards raise the flag at 0600 hours.", ["The guards rise the flag at 0600 hours.", "The guards arise the flag at 0600 hours.", "The guards rose the flag at 0600 hours."],
 "\"Raise\" takes an object: you raise something, such as a flag. \"Rise\" (rise, rose, risen) has no object: the sun rises, and the flag rises when someone raises it."),
("Which sentence states an imagined condition correctly?",
 "If I were you, I would revise daily.", ["If I am you, I would revise daily.", "If I will be you, I would revise daily.", "If I have been you, I would revise daily."],
 "An imagined condition takes the subjunctive \"were\" in formal English. \"Am\" and \"will be\" describe real or future situations and clash with \"would\"."),
("Which sentence uses \"beside\" or \"besides\" correctly?",
 "Besides rifles, the store holds radios.", ["Beside rifles, the store holds radios.", "The sentry stood besides the gate.", "The store holds radios beside of rifles."],
 "\"Besides\" means \"in addition to\"; \"beside\" means \"next to\". The sentry stood beside the gate, and the store holds radios besides rifles."),
("Which sentence uses the correct preposition after \"different\"?",
 "The new kit is different from the old one.", ["The new kit is different of the old one.", "The new kit is different with the old one.", "The new kit is different on the old one."],
 "\"Different from\" is the standard form in formal English. \"Different of\", \"different with\" and \"different on\" are not used."),
("Which sentence means that the match was cancelled?",
 "The match was called off.", ["The match was called up.", "The match was called out.", "The match was called in."],
 "To \"call off\" an event is to cancel it. To \"call up\" is to summon someone, for example for military service."),
("Which sentence uses \"let\" correctly?",
 "The officer let him go home early.", ["The officer let him to go home early.", "The officer let him went home early.", "The officer let he go home early."],
 "\"Let\" takes an object pronoun and the bare infinitive without \"to\": \"let him go\"."),
("Which sentence uses \"affect\" or \"effect\" correctly?",
 "The heat did not affect the parade.", ["The heat did not effect the parade.", "The heat had no affect on the parade.", "The heat did not affected the parade."],
 "\"Affect\" is the usual verb (to have an influence on), and \"effect\" is the usual noun (a result): the heat had no effect on the parade. After \"did not\", the verb stays in its plain form."),
("Which of these words is spelt correctly?",
 "lieutenant", ["leiutenant", "lieutenent", "lutenant"],
 "\"Lieutenant\" is spelt l-i-e-u-t-e-n-a-n-t. The \"ie\" at the start and the \"-ant\" ending are the usual mistakes."),
("Which spelling is correct for the word meaning strict training and obedience to rules?",
 "discipline", ["dicipline", "disciplin", "disipline"],
 "The word is spelt d-i-s-c-i-p-l-i-n-e, with \"sc\" in the middle and a final e."),
("Which sentence means that the rules were openly broken?",
 "They flouted the rules.", ["They flaunted the rules.", "They floated the rules.", "They flooded the rules."],
 "To \"flout\" a rule is to break it openly. To \"flaunt\" something is to show it off, a word often confused with \"flout\"."),
("Which sentence uses the correct preposition after \"insisted\"?",
 "She insisted on seeing the manager.", ["She insisted in seeing the manager.", "She insisted for seeing the manager.", "She insisted at seeing the manager."],
 "The verb \"insist\" takes the preposition \"on\": you insist on something or on doing something."),
("Which sentence uses \"older\" or \"elder\" correctly?",
 "Ada is older than her cousin.", ["Ada is elder than her cousin.", "Ada is more older than her cousin.", "Ada is the elder than her cousin."],
 "\"Elder\" is used before a noun (\"my elder sister\") but never with \"than\". With \"than\", use \"older\"; \"more older\" doubles the comparative."),
("Which sentence spells the word for \"not moving\" correctly?",
 "The lorry was stationary at the checkpoint.", ["The lorry was stationery at the checkpoint.", "The lorry was stationnary at the checkpoint.", "The lorry was stationarry at the checkpoint."],
 "\"Stationary\" with an a means standing still. \"Stationery\" with an e means writing materials such as paper and envelopes."),
("Which sentence puts the adjectives in the usual English order?",
 "He bought a small black leather bag.", ["He bought a black small leather bag.", "He bought a leather small black bag.", "He bought a small leather black bag."],
 "Adjectives usually go in the order size, then colour, then material: small, black, leather. Other orders sound wrong to a native speaker."),
("Which sentence uses the noun \"equipment\" correctly?",
 "The equipment is checked daily.", ["The equipments are checked daily.", "The equipment are checked daily.", "An equipment is checked daily."],
 "\"Equipment\" is an uncountable noun: it has no plural, takes a singular verb and does not take \"an\"."),
("Which sentence uses \"used to\" correctly to mean accustomed to?",
 "She is used to waking early.", ["She is used to wake early.", "She is use to waking early.", "She used to waking early."],
 "\"Be used to\" means be accustomed to, and the \"to\" is a preposition, so it takes the -ing form: \"is used to waking\"."),
("What is the correct plural of \"passer-by\"?",
 "passers-by", ["passer-bys", "passers-bys", "passer-by's"],
 "In a compound like this, the main noun takes the plural: \"passer\" becomes \"passers\" and \"by\" stays the same."),
("Which sentence has the correct question tag?",
 "You are coming with us, aren't you?", ["You are coming with us, isn't it?", "You are coming with us, are you?", "You are coming with us, don't you?"],
 "A positive statement with \"are\" takes the negative tag \"aren't you\". \"Isn't it\" is a common error: it does not match the subject \"you\"."),
("Which sentence uses the past tense of \"lie\" (to rest flat) correctly?",
 "The wounded man lay still until help came.", ["The wounded man laid still until help came.", "The wounded man lied still until help came.", "The wounded man layed still until help came."],
 "\"Lie\" meaning to rest flat goes lie, lay, lain. \"Laid\" is the past of \"lay\" (to put something down), \"lied\" is the past of \"lie\" meaning to tell an untruth, and \"layed\" is not a word."),
("With \"as ... as\", which sentence is correct?",
 "Amina speaks English as fluently as Ada.", ["Amina speaks English as fluent as Ada.", "Amina speaks English as more fluently as Ada.", "Amina speaks English so fluent as Ada."],
 "The word describes how she speaks, so it must be the adverb \"fluently\". The pattern \"as ... as\" takes the plain form, not \"more\"."),
("Which sentence uses the past tense of \"lead\" correctly?",
 "The captain led the patrol home.", ["The captain lead the patrol home.", "The captain leaded the patrol home.", "The captain has lead the patrol home."],
 "The past tense and past participle of \"lead\" are both \"led\". Writing \"lead\" for the past tense is a common spelling slip."),
("Which sentence uses the verb \"swim\" correctly?",
 "She has swum across the river.", ["She has swam across the river.", "She has swimmed across the river.", "She has swammed across the river."],
 "The forms are swim, swam, swum. After \"has\" or \"have\", use the past participle \"swum\"."),
("Which sentence uses the noun \"advice\" correctly?",
 "He gave me some good advice.", ["He gave me some good advices.", "He gave me a good advices.", "He gave me an advices."],
 "\"Advice\" is an uncountable noun, so it has no plural and does not take \"a\". To count it, say \"a piece of advice\"."),
("In the passive, which sentence is correct?",
 "They were made to climb the hill.", ["They were made climb the hill.", "They were made climbing the hill.", "They were made to climbed the hill."],
 "In the active, \"we made them climb\" has no \"to\", but the passive needs it: \"they were made to climb\"."),
("Which sentence uses \"it is high time\" correctly?",
 "It is high time we prepared.", ["It is high time we prepare.", "It is high time we are preparing.", "It is high time we will prepare."],
 "\"It is high time\" is followed by a past-tense verb even though it refers to now: \"It is high time we prepared.\""),
("Which sentence uses the correct preposition after \"congratulated\"?",
 "They congratulated him on his promotion.", ["They congratulated him for his promotion.", "They congratulated him at his promotion.", "They congratulated him about his promotion."],
 "You congratulate someone on something. \"Congratulate for\" is a common error."),
("Which sentence uses the reflexive pronoun correctly?",
 "Musa and Bola helped themselves.", ["Musa and Bola helped theirselves.", "Musa and Bola helped themself.", "Musa and Bola helped their selves."],
 "The reflexive pronoun for \"they\" is \"themselves\". \"Theirselves\" is not standard English."),
]
